using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class AntonioGramsci
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Anzitutto l'operaio deve negare recisamente qualsiasi solidarietà col giornale borghese. Egli dovrebbe ricordarsi sempre, sempre, sempre, che il giornale borghese (qualunque sia la sua tinta) è uno strumento di lotta mosso da idee e da interessi che sono in contrasto coi suoi.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Tutto ciò che stampa è costantemente influenzato da un'idea: servire la classe dominante, che si traduce ineluttabilmente in un fatto: combattere la classe lavoratrice. E difatti, dalla prima all'ultima riga, il giornale borghese sente e rivela questa preoccupazione.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Chi ha fede, chi solo alla realtà attinge l'energia necessaria per combattere le lotte sociali deve rimanere sul terreno della violenza contro la violenza e non subirà umiliazioni.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Dire la verità, arrivare insieme alla verità, è compiere azione comunista e rivoluzionaria.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Fino all'avvento della Sinistra al potere, Lo stato italiano ha dato il suffragio solo alla classe proprietaria, è stato una dittatura feroce che ha messo a ferro e a fuoco l'Italia meridionale e le isole, crocifiggendo, squartando, seppellendo vivi i contadini poveri che gli scrittori salariati tentarono infamare col marchio di «briganti».", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Ebbene, anche per la pace la posizione dei cattolici è in antitesi stridente con la nostra. Aspettano la redenzione dalla grazia, essi, invocano la buona volontà dei santi, quando sarebbe più opportuno fare appello a quella degli uomini.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Per essi vale solo l'autorità, la rivelazione, la parola di Dio, poiché pongono la scaturigine dei fatti umani fuori dell'uomo, in una volontà suprema che tutto abbraccia e tutto giudica, e spartisce il torto o la ragione al lume di una semitica concezione del bene e del male che può valere per gli schiavi, non per gli uomini.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Noi non aspettiamo nulla da altri che da noi stessi; la nostra coscienza di uomini liberi ci impone un dovere, e la nostra forza organizzata lo attua.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Solo ciò che è opera, conquista nostra, ha valore per noi, diventa parte di noi stessi, non ciò che viene elargito da un potere superiore, sia esso lo Stato borghese, o sia la Madonna della Consolata.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Non è quindi solo la ripugnanza per il rito, per l'esteriorità, per il simbolismo ormai vuoto di ogni contenuto di fede che, a malgrado gli sforzi dialettici di qualche abile casuista, ci tiene lontani dal cattolicismo. È l'antitesi insanabile delle idee.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Fino a quando sussiste il regime borghese, col monopolio della stampa in mano al capitalismo e quindi con la possibilità per il governo e per i partiti borghesi di impostare le quistioni politiche a seconda dei loro interessi, presentati come interessi generali, fino a quando sarà soppressa e limitata la libertà di associazione e di riunione della classe operaia o potranno essere diffuse impunemente le menzogne più impudenti contro il comunismo, è inevitabile che le classi lavoratrici rimangano disgregate, cioè abbiano parecchie volontà.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Il fascismo ha trasformato il nostro popolo, gli ha dato una tempra più robusta, una moralità più sana, una resistenza al male che prima era ignorata, una profondità di sentimenti che non era mai esistita.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Il giornale non dovrà avere alcuna indicazione di partito. Dovrà essere un giornale di sinistra.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Il Goethe aveva ragione nel demolire la leggenda del «lazzaronismo » organico dei napoletani e nel rilevare invece che essi sono molto attivi e industriosi. Ma la quistione consiste nel vedere quale sia il risultato effettivo di questa industriosità: essa non è produttiva e non è rivolta a soddisfare i bisogni e le esigenze di classi produttive.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Questa struttura economico-sociale di Napoli spiega molta parte della storia di Napoli, città cosi piena di apparenti contraddizioni e di spinosi problemi politici.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Il Vaticano rappresenta la più grande forza reazionaria esistente in Italia. Per la Chiesa, sono dispotici i governi che intaccano i suoi privilegi e provvidenziali quelli che, come il fascismo, li accrescono.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Io, caro amico, non potrò mai abbandonare gli studi che sono la mia unica speranza di vivere onoratamente quando sarò adulto, perché come sai, la mia famiglia non è ricca di beni di fortuna.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Chi non studia in gioventù se ne pentirà amaramente nella vecchiaia. Un rovescio di fortuna, una lite perduta, possono portare alla miseria il più ricco degli uomini.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Torna agli studi e vi troverai tutti i beni possibili.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Istruitevi, perché avremo bisogno di tutta la nostra intelligenza. Agitatevi, perché avremo bisogno di tutto il nostro entusiasmo. Organizzatevi, perché avremo bisogno di tutta la nostra forza.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "L'acqua è acqua pura e libera quando scorre fra le due rive di un ruscello o di un fiume, non quando è sparsa caoticamente sul suolo, o rarefatta si libra nell'atmosfera. Chi non segue una disciplina politica è appunto materia allo stato gassoso, o materia bruttata da elementi estranei: pertanto inutile e dannosa.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "La disciplina politica fa precipitare queste lordure, e dà allo spirito il suo metallo migliore, alla vita uno scopo, senza del quale la vita non varrebbe la pena di essere vissuta.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "L'illusione è la gramigna più tenace della coscienza collettiva; la storia insegna, ma non ha scolari.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "L'indifferenza opera potentemente nella storia. Opera passivamente, ma opera.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "L'Italia è diventata un mercato di sfruttamento coloniale, una sfera d'influenza, un dominion, una terra di capitolazioni, tutto fuorché uno Stato indipendente e sovrano. Ciò ha prodotto la politica forsennata della classe dirigente italiana, queste sono le magnifiche sorti progressive che sono state assicurate al popolo italiano dagli intrighi mercantili del capitalismo in caccia di maggiori profitti.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Ebbene, il popolo italiano reagisce contro questa condizione di fatto; reagisce con l'azione della parte sua che non è compromessa nell'avventura della guerra, che non ha abdicato al suo diritto sovrano di essere qualcuno nella storia del mondo, che non vuole essere serva né di tedeschi, né di inglesi, e tanto meno serva della serva.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Quanto più la classe dirigente ha precipitato in basso la nazione italiana, tanto più aspro sacrificio deve sostenere il proletariato per ricreare alla nazione una personalità storica indipendente; quanto piú la classe dirigente ha permesso che l'organismo economico-politico italiano fosse avvinto strettamente al carro imperiale britannico, tanto piú grande sforzo deve compiere il proletariato per divincolarsi, per riacquistare la libertà di movimento e di iniziativa nella storia.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "La cultura [...] è organizzazione, disciplina del proprio io interiore; è presa di possesso della propria personalità, e conquista di coscienza superiore, per la quale si riesce a comprendere il proprio valore storico, la propria funzione nella vita, i propri diritti, i propri doveri.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "La sfiducia reciproca, il sottinteso sleale corrodono nel nostro paese tutte le forme di rapporti: i rapporti tra singolo e singolo, i rapporti tra singolo e collettività. L'ipocrisia del carattere italiano è in dipendenza assoluta con la mancanza di libertà.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "La verità è che la Sicilia conserva una sua indipendenza spirituale, e questa si rivela piú spontanea e forte che mai nel teatro.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Marx è stato grande, la sua azione è stata feconda, non perché abbia inventato dal nulla, non perché abbia estratto dalla sua fantasia una visione originale della storia, ma, perché il frammentario, l'incompiuto, l'immaturo è in lui diventato maturità, sistema, consapevolezza.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Marx si pianta nella storia con la solida quadratura di un gigante.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Marx significa ingresso dell'intelligenza nella storia dell'umanità, regno della consapevolezza.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Nella coscienza delle masse, anche delle più arretrate, è scaduto il prestigio e la riverenza per le istituzioni, e queste, svuotate di ogni spirito, private di ogni moralità, sopravvivono solo come paurosi vampiri.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Non ho mai voluto mutare le mie opinioni, per le quali sarei disposto a dare la vita e non solo a stare in prigione.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Non si imparava il latino e il greco per parlarli, per fare i camerieri, gli interpreti, i corrispondenti commerciali. Si imparava per conoscere direttamente la civiltà dei due popoli, presupposto necessario della civiltà moderna, cioè per essere se stessi e conoscere se stessi consapevolmente.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Odio gli indifferenti. Credo come Federico Hebbel che «vivere vuol dire essere partigiani». Non possono esistere i solamente uomini, gli estranei alla città. Chi vive veramente non può non essere cittadino, e parteggiare.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Indifferenza è abulia, è parassitismo, è vigliaccheria, non è vita. Perciò odio gli indifferenti.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Ogni mattino, quando mi risveglio ancora sotto la cappa dei cielo, sento che per me è capodanno.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Perciò odio questi capodanni a scadenza fissa che fanno della vita e dello spirito umano un'azienda commerciale col suo bravo consuntivo, e il suo bilancio e il preventivo per la nuova gestione.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Essi fanno perdere il senso della continuità della vita e dello spirito. Si finisce per credere sul serio che tra anno e anno ci sia una soluzione di continuità e che incominci una novella istoria, e si fanno propositi e ci si pente degli spropositi, ecc. ecc. È un torto in genere delle date.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Aspetto il socialismo anche per questa ragione. Perché scaraventerà nell'immondezzaio tutte queste date che ormai non hanno più nessuna risonanza nel nostro spirito e, se ne creerà delle altre, saranno almeno le nostre, e non quelle che dobbiamo accettare senza beneficio d'inventario dai nostri sciocchissimi antenati.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Ogni movimento rivoluzionario è romantico, per definizione.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Solo chi fortemente vuole identifica gli elementi necessari alla realizzazione della sua volontà.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Solo un fascista, Aldo Palazzeschi, era contro la guerra. Egli ha rotto con il movimento e, quantunque fosse uno degli scrittori più interessanti, ha finito col tacere come letterato.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Tutti gli uomini sono intellettuali, [...] ma non tutti gli uomini hanno nella società la funzione di intellettuali (così, perché può capitare che ognuno in qualche momento si frigga due uova o si cucisca uno strappo della giacca, non si dirà che tutti sono cuochi e sarti).", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Voi fascisti porterete l'Italia alla rovina, e a noi comunisti spetterà salvarla!", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Occorre distruggere il pregiudizio molto diffuso che la filosofia sia un alcunché di molto difficile per il fatto che essa è l'attività intellettuale propria di una determinata categoria di scienziati specialisti o di filosofi professionali e sistematici.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Occorre pertanto dimostrare preliminarmente che tutti gli uomini sono «filosofi», definendo i limiti e i caratteri di questa «filosofia spontanea», propria di «tutto il mondo», e cioè della filosofia che è contenuta: 1) nel linguaggio stesso, che è un insieme di nozioni e di concetti determinati e non già e solo di parole grammaticalmente vuote di contenuto; 2) nel senso comune e buon senso; 3) nella religione popolare e anche quindi in tutto il sistema di credenze, superstizioni, opinioni, modi di vedere e di operare che si affacciano in quello che generalmente si chiama «folclore».", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Chi parla solo il dialetto o comprende la lingua nazionale in gradi diversi, partecipa necessariamente di una intuizione dei mondo più o meno ristretta e provinciale, fossilizzata, anacronistica in confronto delle grandi correnti di pensiero che dominano la storia mondiale.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "I suoi interessi saranno ristretti, piú o meno corporativi o economistici, non universali.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Se non sempre è possibile imparare piú lingue straniere per mettersi a contatto con vite culturali diverse, occorre almeno imparare bene la lingua nazionale.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Una grande cultura può tradursi nella lingua di un'altra grande cultura, cioè una grande lingua nazionale, storicamente ricca e complessa, può tradurre qualsiasi altra grande cultura, cioè essere una espressione mondiale. Ma un dialetto non può fare la stessa cosa.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Comprendere e valutare realisticamente la posizione e le ragioni dell'avversario (e talvolta è avversario tutto il pensiero passato) significa appunto essersi liberato dalla prigione delle ideologie (nel senso deteriore, di cieco fanatismo ideologico), cioè porsi da un punto di vista «critico», l'unico fecondo nella ricerca scientifica.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "L'affermazione di Feuerbach: «L'uomo è quello che mangia», può essere, presa in sé, interpretata variamente. Interpretazione gretta e stolta: cioè l'uomo è volta per volta quello che mangia materialmente, cioè i cibi hanno una immediata influenza determinatrice sul modo di pensare.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Se questa affermazione fosse vera, la storia avrebbe la sua matrice determinante nella cucina e le rivoluzioni coinciderebbero coi mutamenti radicali dell'alimentazione di massa. Il contrario è storicamente vero: cioè sono le rivoluzioni e il complesso sviluppo storico che hanno modificato l'alimentazione e creato i «gusti» successivi nella scelta dei cibi.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "La massima di E. Kant: «Opera in modo che la tua condotta possa diventare una norma per tutti gli uomini, in condizioni simili» [...] può essere considerata un truismo, poiché è difficile trovare uno che non operi credendo di trovarsi nelle condizioni in cui tutti opererebbero come lui.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "La quarta guerra del Risorgimento italiano non pare debba avere per il Mezzogiorno conseguenze diverse da quella delle altre tre.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Le paterne amministrazioni di Spagna e dei Borboni nulla avevano creato: la borghesia non esisteva, l'agricoltura era primitiva e non bastava neppure a soddisfare il mercato locale; non strade, non porti, non utilizzazione delle poche acque che la regione, per la sua speciale conformazione geologica, possedeva.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Giustino Fortunato e Benedetto Croce rappresentano [...] le chiavi di volta del sistema meridionale e, in un certo senso, sono le due più grandi figure della reazione italiana.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Cosa significa e cosa può e dovrebbe significare la parola d'ordine di Giovanni Gentile: «Torniamo al De Sanctis!»? Significa «tornare» meccanicamente ai concetti che il De Sanctis svolse intorno all'arte e alla letteratura, o significa assumere verso l'arte e la vita un atteggiamento simile a quello assunto dal De Sanctis ai suoi tempi?", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Tra il Manzoni e gli «umili» c'è distacco sentimentale; gli umili sono per il Manzoni un «problema di storiografia», un problema teorico che egli crede di poter risolvere col romanzo storico, col «verosimile» del romanzo storico.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Papini è cattolico e anticrociano; le contraddizioni del suo superficiale scritto risultano da questa doppia qualità.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Anche la letteratura commerciale non dev'essere trascurata nella storia della cultura: essa anzi ha un valore grandissimo proprio da questo punto di vista, perché il successo di un libro di letteratura commerciale indica (e spesso è il solo indicatore esistente) quale sia la «filosofia dell'epoca», cioè quale massa di sentimenti e di concezioni del mondo predomini nella moltitudine «silenziosa».", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Questa letteratura è uno «stupefacente» popolare, è un «oppio».", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Il romanzo d'appendice sostituisce (e favorisce nel tempo stesso) il fantasticare dell'uomo del popolo, è un vero sognare ad occhi aperti.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Si può vedere ciò che sostengono Freud e i psicanalisti sul sognare ad occhi aperti. In questo caso si può dire che nel popolo il fantasticare è dipendente dal «complesso di inferiorità» (sociale) che determina lunghe fantasticherie sull'idea di vendetta, di punizione dei colpevoli dei mali sopportati, ecc.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Don Chisciotte non cerca di evadere anch'egli, anche praticamente, dal tritume e dalla standardizzazione della vita quotidiana di un villaggio spagnolo?", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Raskolnikov è Montecristo «criticato» da un panslavista-cristiano.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "L'Ojetti è rappresentativo da più punti di vista: ma la codardia intellettuale dell' uomo supera ogni misura normale.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Papini ha esercitato tutti i mestieri, per poi sporcificarli tutti: il filosofo, per concludere che la filosofia è una specie di cancrena al cervelletto, il cattolico, per incenerare l'universo con un appropriato dizionario, il letterato, per sancir da ultimo che della letteratura non sappiamo che farcene.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Ciò non toglie che Papini non si sia conquistato un posticino nella storia della letteratura dentro il capitolo i \"polemisti\".", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Papini è sempre stato un «polemista» nel senso che dice il Volpicelli, e lo è ancor oggi, poiché non si sa se nell'espressione «polemista cattolico» a Papini interessi più il sostantivo o l'aggettivo. Col suo «cattolicismo» Papini avrebbe voluto dimostrare di non essere un puro «polemista», cioè un «calligrafo», un funambolo della parola e della tecnica, ma non c'è riuscito!", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "L'avventura è il dominio dell'imprevisto, della vita che fiorisce spontaneamente nuova e attuale dal suo morto passato.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Siamo assolutamente separati dai coatti comuni, la cui vita non saprei descriverti con brevi tratti: ricordi la novella di Kipling intitolata: ''Una strana cavalcata'' nel volume francese ''L'uomo che volle essere re''. Mi è balzata di colpo alla memoria tanto mi sembrava di viverla.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "La mia vita scorre sempre uguale. Leggo, mangio, dormo e penso.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Tu però non devi pensare a tutto ciò che pensi e specialmente non devi farti illusioni. Non perché io non sia arcisicuro di rivederti e di farti conoscere i miei bambini, ma perché sono anche arcisicuro che sarò condannato e chissà a quanti anni.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Tu sai come si fa coi bambini che fanno la pipì nel letto, è vero? Si minaccia di bruciarli con la stoppa accesa in cima al forcone. Ebbene: immagina che in italia ci sia un bambino molto grosso che minaccia continuamente di fare la pipì nel letto di questa grande genitrice di biade e di eroi; io e qualche altro siamo la stoppa (o il cencio) accesa che si mostra per minacciare l'impertinente e impedirgli di insudiciare le candide lenzuola.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Poiché le cose sono così, non bisogna né allarmarsi, né illudersi; bisogna solo attendere con grande pazienza e sopportazione.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Ma, in verità, mi sono accorto che, proprio al contrario di quanto avevo sempre pensato, in carcere si studia male, per tante ragioni, tecniche e psicologiche.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Mi sono convinto che anche quando tutto è o pare perduto, bisogna rimettersi tranquillamente all'opera, ricominciando dall'inizio.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Mi sono convinto che bisogna sempre contare solo su se stessi e sulle proprie forze; non attendersi niente da nessuno e quindi non procurarsi delusioni.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Che occorre proporsi di fare solo ciò che si sa e si può fare e andare per la propria via.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "La mia posizione morale è ottima: chi mi crede un satanasso, chi mi crede quasi un santo.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Io non voglio fare né il martire né l'eroe. Credo di essere semplicemente un uomo medio, che ha le sue convinzioni profonde, e che non le baratta per niente al mondo.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Mi preoccupa molto lo stato d'animo della mamma, d'altronde non so come fare per rassicurarla e consolarla. Vorrei infonderle la convinzione che io sono tranquillissimo, come realmente sono, ma vedo che non riesco.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "C'è tutta una zona di sentimento e di modi di pensare che costituisce una specie di abisso tra noi. Per lei il mio incarceramento è una terribile disgrazia alquanto misteriosa nelle sue concatenazioni di cause ed effetti; per me è un episodio nella lotta politica che si combatteva e si continuerà a combattere non solo in Italia, ma in tutto il mondo, per chissà quanto tempo ancora.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Io sono rimasto preso, così come durante la guerra si poteva cadere prigionieri, sapendo che questo poteva avvenire e che poteva avvenire anche di peggio.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Ma temo che anche tu la pensi come la mamma e che queste spiegazioni ti rassomiglino a un indovinello espresso ancora in una lingua sconosciuta.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Che tu comprendessi bene, anche col sentimento, che io sono un detenuto politico, che non ho e non avrò mai da vergognarmi di questa situazione.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Che, in fondo, la detenzione e la condanna le ho volute io stesso, in certo modo, perché non ho mai voluto mutare le mie opinioni, per le quali sarei disposto a dare la vita e non solo a stare in prigione.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Che perciò io non posso che essere tranquillo e contento di me stesso.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Cara mamma, vorrei proprio abbracciarti stretta stretta perché sentissi quanto ti voglio ti voglio bene e come vorrei consolarti di questo dispiacere che ti ho dato: ma non potevo fare diversamente.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "La vita è così, molto dura, e i figli qualche volta devono dare dei grandi dolori alle loro mamme, se vogliono conservare il loro onore e al loro dignità di uomini.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "I traduttori sono pagati male e traducono peggio.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Io sono morto una volta e poi sono resuscitato, ciò che dimostra che ho sempre avuto la pelle dura.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Da bambino, a 4 anni, ho avuto delle emorragie per tre giorni di seguito, che mi avevano completamente dissanguato, accompagnate da convulsioni.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Il medico mi aveva dato per morto e mia madre ha conservato fino al 914 circa la piccola bara e il vestitino speciale che dovevano servire per seppellirmi; una zia sosteneva che ero resuscitato quando lei mi unse i piedini con l'olio di una lampada dedicata a una madonna e perciò quando mi rifiutavo di compiere gli atti religiosi mi rimproverava aspramente ricordando che alla madonna dovevo la vita, cosa che mi impressionava poco, a dir la verità.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "Lo studio che ho fatto sugli intellettuali è molto vasto come disegno e in realtà non credo che esistano in Italia libri su questo argomento. Esiste certo molto materiale erudito ma disperso in un numero infinito di riviste e archivi storici locali.", Author = "Antonio Gramsci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Antonio_Gramsci", Text = "D'altronde io estendo molto la nozione di intellettuale e non mi limi", Author = "Antonio Gramsci" },
        };
    }
}